nta.declaration:
// Place global declarations here.


/************************************************************
 *                     MAP CONSTANTS
 ************************************************************/

const int WIDTH  = 18;
const int HEIGHT = 13;
const int BORDER_DELAY = 2;

const int MAX_LIVES = 5;
const int NUM_HOME_BAYS = 5;

const int INITIAL_TIME_LIMIT = 300;   // 30 s

const int MAX_PER_ROW = 4;
const int NUM_MOVING_ROWS = 12;

const int TIME_UNITS_PER_SECOND = 10;
const int TOTAL_LOOP = WIDTH + BORDER_DELAY;

/************************************************************
 *                    ENUMERATIONS
 ************************************************************/

typedef int[0,3] TileType;

const TileType SAFE  = 0;
const TileType ROAD  = 1;
const TileType RIVER = 2;
const TileType HOME  = 3;

typedef int[0,4] ObjectType;

const ObjectType VEHICLE        = 0;
const ObjectType TRUCK          = 1;
const ObjectType LOG            = 2;
const ObjectType TURTLE         = 3;
const ObjectType DIVING_TURTLE  = 4;

/************************************************************
 *              IMMUTABLE OBJECT DESCRIPTION
 ************************************************************/


typedef struct
{
    int row;                    // y coordinate
    int size;                   // vehicle length
    int speed;                  // movement period
    bool moveLeft;               // if true, then the object moves from right to left
    ObjectType type;
    int numObjects;
    int initialX[MAX_PER_ROW];
} RowInfo;

int currentLevel = 1;


/************************************************************
 *              MUTABLE OBJECT STATE
 ************************************************************/

typedef struct
{
    int x[MAX_PER_ROW];
} RowState;

/************************************************************
 *                GAME STATE VARIABLES
 ************************************************************/

int frog_x = 9;
int frog_y = 0;

int score = 0;
int lives = MAX_LIVES;

bool bayOccupied[NUM_HOME_BAYS] =
{
    false,false,false,false,false
};

int[0, INITIAL_TIME_LIMIT] globalTick = 0;
int currentLevelTimeLimit = 300;

/************************************************************
 *                 STATIC MAP
 ************************************************************/

const TileType map[HEIGHT] =
{
    SAFE,   // 0
    ROAD,   // 1
    ROAD,   // 2
    ROAD,   // 3
    ROAD,   // 4
    ROAD,   // 5
    SAFE,   // 6
    RIVER,  // 7
    RIVER,  // 8
    RIVER,  // 9
    RIVER,  //10
    RIVER,  //11
    HOME    //12
};

/************************************************************
 *              SYNCHRONIZATION CHANNELS
 ************************************************************/

chan moveHop;

broadcast chan tick;
broadcast chan restart;

broadcast chan frogDies;
broadcast chan reachBay;

broadcast chan finishLevel;

/************************************************************
 *            OBJECT DECLARATIONS
 ************************************************************/
const RowInfo rowInfo[NUM_MOVING_ROWS] =
{
    //row,size,speed,left,type,numObj,{positions}

    {1,1,3,true ,VEHICLE,2,{4,14,0,0}},

    {2,1,10,false,VEHICLE,2,{2,11,0,0}},

    {3,1,5,true ,VEHICLE,4,{4,8,13,17}},

    {4,1,4,false,VEHICLE,2,{2,10,0,0}},

    {5,2,7,true ,TRUCK,2,{4,15,0,0}},

    // 7: RIVER - Turtles & Diving Turtles moving Left
    // currently the turtles are unified in the groups of 5 cells

    {7, 5, 6, true, TURTLE, 1, {5, 0, 0, 0}}, 
    {7, 5, 6, true, DIVING_TURTLE, 1, {13, 0, 0, 0}}, 

    // 8: RIVER - Small Logs moving Right
    {8, 3, 2, false, LOG, 3, {7, 11, 15, 0}},

    // 9: RIVER - Giant Log moving Right
    {9, 9, 7, false, LOG, 1, {3, 0, 0, 0}},

    // 10: RIVER - Turtles & Diving Turtles moving Left
    // currently the turtles are unified in the groups of 3 cells
    {10, 3, 2, true, TURTLE, 1, {1, 0, 0, 0}},
    {10, 3, 2, true, DIVING_TURTLE, 1, {9, 0, 0, 0}},

    // 11: RIVER - Medium Logs moving Right
    {11, 5, 2, false, LOG, 2, {1, 11, 0, 0}}
};

RowState rowState[NUM_MOVING_ROWS];



//------------------------------------------------------INIT---------------------------
void initializeRows()
{
    int r,c;

    for(r=0;r<NUM_MOVING_ROWS ;r++)
    {
        for(c=0;c<rowInfo[r].numObjects;c++)
        {
            rowState[r].x[c]=rowInfo[r].initialX[c];
        }
    }
}

void clearHomeBays()
{
    int i;

    for(i = 0; i < NUM_HOME_BAYS; i++)
        bayOccupied[i] = false;
}

int getCurrentTimeLimit()
{
    return (32 - 2 * currentLevel) * TIME_UNITS_PER_SECOND;
}

void restartLevel()
{
    globalTick = 0;
    initializeRows();

    frog_x = 9;
    frog_y = 0;

    // later:
    // initialize turtles
    // initialize logs
    // reset score if starting a new game
}

void initializeGame()
{
    initializeRows();
    clearHomeBays();

    frog_x = 9;
    frog_y = 0;

    score = 0;
    lives = MAX_LIVES;

    globalTick = 0;
    currentLevelTimeLimit = getCurrentTimeLimit();
}
//------------------------------------------------------ROWS---------------------------

//shift all the objects in the row simultaneously 
void moveRow(int y)
{
    int obj;
    for(obj = 0; obj < rowInfo[y].numObjects; obj++)
    {
        if(rowInfo[y].moveLeft)
        {
            rowState[y].x[obj]--;
            if (rowState[y].x[obj] < 0) {
                rowState[y].x[obj] = TOTAL_LOOP - 1; // Wraps directly to 19
            }
        }
        else
        {
            rowState[y].x[obj]++;
            if (rowState[y].x[obj] >= TOTAL_LOOP) {
                rowState[y].x[obj] = 0; // Wraps directly to 0
            }
        }
    }
}

//checks if it is the time to move the Objects for the given row
void updateRow(int y)
{
    if(globalTick % rowInfo[y].speed == 0)
        moveRow(y);
}

//------------------------------------------------------TURTLES---------------------------


//------------------------------------------------------FROGGER---------------------------

// Returns true if a specific visible X coordinate (0 to 17) is blocked by object 'obj' in row 'y'
bool isCellOccupied(int y, int obj, int target_x)
{
    int size = rowInfo[y].size;
    bool moveLeft = rowInfo[y].moveLeft;
    int frontX = rowState[y].x[obj];
    int i;

    for(i = 0; i < size; i++)
    {
        int bodyPartX;
        if (moveLeft) {
            // Tail stretches to the right in our loop
            bodyPartX = (frontX + i + TOTAL_LOOP) % TOTAL_LOOP;
        } else {
            // Tail stretches to the left in our loop
            bodyPartX = (frontX - i + TOTAL_LOOP) % TOTAL_LOOP;
        }

        // If this specific body segment matches the frog's visible X position
        if (bodyPartX == target_x) {
            return true;
        }
    }
    return false;
}

// Returns true if ANY object in row 'y' hits the given visible x position
bool isRowHittingFrog(int y, int target_x)
{
    int obj;
    // Map array maps 1-indexed row data from rowInfo to actual height index if needed,
    // otherwise adjust 'y' to match your rowInfo array boundary

    for(obj = 0; obj < rowInfo[y].numObjects; obj++)
    {
        if (isCellOccupied(y, obj, target_x)) {
            return true;
        }
    }
    return false;
}


bool checkCollision()
{
    // Safe rows or Win row -> No collision danger
    if (map[frog_y] == SAFE || map[frog_y] == HOME)
    {
        return false; 
    }

    // Road Rows: If you hit an object, you die
    if (map[frog_y] == ROAD)
    {
        if (isRowHittingFrog(frog_y, frog_x)) {
            return true; 
        }
    }

    // River Rows: You MUST be on an object. If you aren't, you drown!
    if (map[frog_y] == RIVER)
    {
        if (!isRowHittingFrog(frog_y, frog_x)) {
            return true; // Drowned in the river
        }
    }

    return false;
}

nta.system:
